<template><AppPage :title="item?.resource.provenance.name || 'Load balancer'" subtitle="Server-resolved selector targets"><v-alert v-if="error" type="error" variant="tonal">{{ error }}</v-alert><v-skeleton-loader v-else-if="loading" type="heading,card"/><template v-else-if="item&&graph"><div class="counts"><div><span>Matched NICs</span><strong>{{ count('nic') }}</strong></div><div><span>Matched VMs</span><strong>{{ count('vm') }}</strong></div><div><span>Matched zones</span><strong>{{ count('zone') }}</strong></div></div><v-card variant="outlined" class="mt-5"><v-card-title>Selector relationships</v-card-title><v-card-subtitle>Counts and edges come from server-side selector resolution.</v-card-subtitle><v-card-text><EvidenceGraph :graph="graph" :root-key="item.resource.key"/></v-card-text></v-card></template></AppPage></template>
<script setup lang="ts">
import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{sreApi,type SreGraph,type SreResourceDTO}from'@/api/sre';import AppPage from'@/components/app/AppPage.vue';import EvidenceGraph from'@/components/sre/EvidenceGraph.vue'
const route=useRoute(),item=ref<SreResourceDTO|null>(null),graph=ref<SreGraph|null>(null),loading=ref(true),error=ref<string|null>(null)
const count=(token:string)=>graph.value?.resources.filter(resource=>resource.provenance.kind.toLowerCase().includes(token)).length??0
onMounted(async()=>{try{const id=String(route.params.id),[detail,topology]=await Promise.all([sreApi.loadBalancer(id),sreApi.graph(id)]);item.value=detail.data;graph.value=topology.data}catch(cause){error.value=cause instanceof Error?cause.message:'Load balancer unavailable'}finally{loading.value=false}})
</script>
<style scoped>.counts{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.counts>div{padding:14px;border:1px solid var(--ic-border);border-radius:8px}.counts span{display:block;color:var(--ic-text-muted);font-size:11px;text-transform:uppercase}.counts strong{font-size:24px}@media(max-width:550px){.counts{grid-template-columns:1fr}}</style>
